NS_ENSURE_SUCCESS(rv, rv);

// Is the message already in the offline store?
bool hasOffline;
rv = folder->HasMsgOffline(msgKey, &hasOffline);
NS_ENSURE_SUCCESS(rv, rv);
if (hasOffline) {
  // Yes - start streaming it directly from there.
  return StartMessageReadFromStore(aListener);
}

// No - Fetch it from the server first.
// TODO: Should use nsIStreamListenerTee to combine this into one operation.
// TODO: There should be a policy check - do we actually _want_ to keep a
//       local copy of this message?
return ExchangeFetchMsgsToOffline(
    folder, {msgKey},
    [self = RefPtr(this), ewsFolder,
     listener = nsCOMPtr(aListener)](nsresult status) {
      if (NS_SUCCEEDED(status)) {
        // Let the folder know a message has been downloaded.
        ewsFolder->HandleDownloadedMessages();

        // Yay! We've now got the offline copy in the store.
        // Can start streaming it out now....
        status = self->StartMessageReadFromStore(listener);
      }

      if (NS_FAILED(status)) {
        // We've already returned from AsyncOpen(), so the listener is
        // expecting callbacks...
        listener->OnStartRequest(self);
        listener->OnStopRequest(self, status);

    store->DiscardNewMessage(mFolder, mOut);
  }
} else {
  // Update the database entry for the message to link it to the store.
  MOZ_ASSERT(mOut);

  nsAutoCString storeToken;
  rv = store->FinishNewMessage(mFolder, mOut, storeToken);

  nsCOMPtr<nsIMsgDBHdr> msgHdr;
  if (NS_SUCCEEDED(rv)) {
    rv = mFolder->GetMessageHeader(msgKey, getter_AddRefs(msgHdr));
  }

  if (NS_SUCCEEDED(rv)) {
    rv = msgHdr->SetStoreToken(storeToken);
  }
  if (NS_SUCCEEDED(rv)) {
    rv = msgHdr->SetOfflineMessageSize(mMsgSize);
  }
  // NOTE: we don't set .messageSize. That should already have been set
  // before a download is attempted, having been sent down by the server
  // when it first told us about the existance of the message.
  if (NS_SUCCEEDED(rv)) {
    uint32_t unused;
    rv = msgHdr->OrFlags(nsMsgMessageFlags::Offline, &unused);
  }

// Make sure the message exists in the offline store.
nsMsgKey msgKey;
MOZ_TRY(message->GetMessageKey(&msgKey));

bool hasOffline;
MOZ_TRY(folder->HasMsgOffline(msgKey, &hasOffline));

if (!hasOffline) {
  return NS_ERROR_NOT_AVAILABLE;
}

// Stream the message from the store into the stream listener.
nsCOMPtr<nsIInputStream> msgStream;
MOZ_TRY(folder->GetMsgInputStream(message, getter_AddRefs(msgStream)));

nsCOMPtr<nsIInputStreamPump> pump;
MOZ_TRY(NS_NewInputStreamPump(getter_AddRefs(pump), msgStream.forget()));
